def minSemesters(n, relations):
    adj = [[] for _ in range(n)]
    indeg = [0] * n
    for a, b in relations:
        adj[a].append(b)
        indeg[b] += 1
    layer = [i for i in range(n) if indeg[i] == 0]
    taken = 0
    semesters = 0
    while layer:
        semesters += 1
        taken += len(layer)
        nxt = []
        for u in layer:
            for v in adj[u]:
                indeg[v] -= 1
                if indeg[v] == 0:
                    nxt.append(v)
        layer = nxt
    return semesters if taken == n else -1
